<?php
require_once 'includes/config.php'; require_admin(); $msg=null;$error=null;
$name=trim($_GET['name']??'');$class=(int)($_GET['class']??0);$gender=trim($_GET['gender']??'');
$profileTableExists=(bool)$dbh->query("SELECT COUNT(*) FROM information_schema.tables WHERE table_schema=DATABASE() AND table_name='srms_profile_photos'")->fetchColumn();
$profileSelect=$profileTableExists?"(SELECT stored_filename FROM srms_profile_photos p WHERE p.person_type='student' AND p.person_id=s.StudentId LIMIT 1) AS profile_photo":"CAST(NULL AS CHAR) AS profile_photo";
$sql="SELECT s.*,c.ClassName,c.Section,$profileSelect FROM tblstudents s LEFT JOIN tblclasses c ON c.id=s.ClassId WHERE 1=1";$p=[];if($name!==''){$sql.=' AND s.StudentName LIKE :name';$p[':name']="%$name%";}if($class){$sql.=' AND s.ClassId=:class';$p[':class']=$class;}if($gender!==''){$sql.=' AND s.Gender=:gender';$p[':gender']=$gender;}$sql.=' ORDER BY s.StudentName';$q=$dbh->prepare($sql);$q->execute($p);$rows=$q->fetchAll();$classes=$dbh->query('SELECT id,ClassName,Section FROM tblclasses ORDER BY ClassName,Section')->fetchAll();function student_q($extra=[]){$base=$_GET;foreach($extra as $k=>$v)$base[$k]=$v;return http_build_query($base);}
?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Manage Students | SRMS</title><link rel="stylesheet" href="css/bootstrap.min.css"><link rel="stylesheet" href="css/font-awesome.min.css"><link rel="stylesheet" href="css/main.css"><link rel="stylesheet" href="css/srms-modernization.css"><link rel="stylesheet" href="css/srms-responsive.css"></head><body class="top-navbar-fixed"><div class="main-wrapper"><?php include('includes/topbar.php');?><div class="content-wrapper"><div class="content-container"><?php include('includes/leftbar.php');?><div class="main-page"><div class="container-fluid"><div class="row page-title-div"><div class="col-md-8"><h2 class="title">Student Management</h2></div></div><div class="row"><div class="col-md-12"><div class="panel"><div class="panel-heading"><h5>Search, filter and export students</h5></div><div class="panel-body"><form method="get" class="row"><div class="col-md-3 form-group"><label>Search by name</label><input class="form-control" name="name" value="<?=e($name)?>" placeholder="Student name"></div><div class="col-md-3 form-group"><label>Class</label><select class="form-control" name="class"><option value="0">All classes</option><?php foreach($classes as $c):?><option value="<?=$c['id']?>" <?=$class==$c['id']?'selected':''?>><?=e($c['ClassName'].' - '.$c['Section'])?></option><?php endforeach;?></select></div><div class="col-md-2 form-group"><label>Gender</label><select class="form-control" name="gender"><option value="">All</option><option <?=$gender==='Male'?'selected':''?>>Male</option><option <?=$gender==='Female'?'selected':''?>>Female</option><option <?=$gender==='Other'?'selected':''?>>Other</option></select></div><div class="col-md-4 form-group"><label>&nbsp;</label><div><button class="btn btn-primary">Search / Filter</button> <a class="btn btn-default" href="manage-students.php">Reset</a> <a class="btn btn-success" href="add-students.php">+ Register Student</a></div></div></form><div class="m-t-10"><a class="btn btn-info btn-sm" href="export-students.php?<?=student_q(['format'=>'csv'])?>">Export CSV</a> <a class="btn btn-danger btn-sm" href="export-students.php?<?=student_q(['format'=>'pdf'])?>">Export PDF</a></div></div></div></div></div><div class="panel"><div class="panel-heading"><h5>Registered Students (<?=count($rows)?>)</h5></div><div class="panel-body"><div class="table-responsive"><table class="table table-bordered table-striped"><thead><tr><th>#</th><th>Photo</th><th>Student</th><th>Roll ID</th><th>Class</th><th>Gender</th><th>Email</th><th>Next of Kin</th><th>Phone</th><th>Status</th><th>Action</th></tr></thead><tbody><?php $i=1;foreach($rows as $r):?><tr><td><?=$i++?></td><td><?php if(!empty($r['profile_photo'])):?><img src="profile-photo.php?type=student&amp;id=<?=$r['StudentId']?>" alt="Student photo" width="42" height="42" style="object-fit:cover;border-radius:50%"><?php else:?>—<?php endif;?></td><td><?=e($r['StudentName'])?></td><td><?=e($r['RollId'])?></td><td><?=e($r['ClassName'].' - '.$r['Section'])?></td><td><?=e($r['Gender'])?></td><td><?=e($r['StudentEmail'])?></td><td><?=e($r['NextOfKinName']?:'—')?></td><td><?=e($r['NextOfKinPhone']?:'—')?></td><td><span class="label label-<?=$r['Status']?'success':'default'?>"><?=$r['Status']?'Active':'Blocked'?></span></td><td><a class="btn btn-primary btn-xs" href="edit-student.php?stid=<?=$r['StudentId']?>">View / Edit</a></td></tr><?php endforeach;if(!$rows):?><tr><td colspan="11" class="text-center">No students match the selected filters.</td></tr><?php endif;?></tbody></table></div></div></div></div></div></div></div></div></body></html>
